-- BANCO FICTICIO PARA DEMO DA URA (todos os dados sao inventados)
-- Cole este arquivo inteiro no SQL Editor do Supabase e clique em Run.

drop table if exists parcelas;
drop table if exists contratos;
drop table if exists clientes;

create table clientes (
  cpf text primary key,
  nome text not null,
  telefone text not null,
  email text not null,
  data_nascimento date,
  pontos integer default 0
);
create index idx_clientes_telefone on clientes (telefone);

create table contratos (
  contrato_id text primary key,
  cpf text not null references clientes (cpf),
  produto text,
  valor_financiado numeric(12,2),
  parcelas_total integer,
  valor_parcela numeric(10,2),
  data_inicio date,
  status text,
  pdf_key text
);

create table parcelas (
  parcela_id text primary key,
  cpf text not null references clientes (cpf),
  contrato_id text not null references contratos (contrato_id),
  numero integer,
  vencimento date,
  valor numeric(10,2),
  status text,            -- paga, aberta ou vencida
  linha_digitavel text,
  pdf_key text
);
create index idx_parcelas_cpf on parcelas (cpf);

-- Seguranca: ninguem acessa sem a chave de servico
alter table clientes enable row level security;
alter table contratos enable row level security;
alter table parcelas enable row level security;

